def metric(data: pd.DataFrame) -> float:
    matches = 0
    total = 0
    for _, row in data.iterrows():
        a = row['option_a_ratings']
        b = row['option_b_ratings']
        for j in range(len(a)):
            if a[j] > b[j]:
                if row['response'] == 1:
                    matches += 1
                total += 1
                break
            elif b[j] > a[j]:
                if row['response'] == 0:
                    matches += 1
                total += 1
                break
    return float(matches / total) if total > 0 else 0.0

